 */
class WebNotice extends Model
{
    protected $table = 'web_notices';

    protected $guarded = ['id'];

    public $timestamps = false;

    protected function casts(): array
    {
        return [
            'city_id' => 'integer',
            'legacy_id' => 'integer',
            'account_id' => 'integer',
            'sender_account_id' => 'integer',
            'project_id' => 'integer',
